export interface BooleanOpOptions extends EntityOptions {
    /** Number of linear segments used to approximate curved Bézier arcs (Default: 24) */
    resolution?: number;

    /** Epsilon threshold for merging collinear vertices and removing numerical noise (Default: 0.005) */
    simplifyTolerance?: number;

    /** Whether to reconstruct smooth cubic Bézier curves instead of faceted polygons (Default: true) */
    reconstructCurves?: boolean;

    /** Minimum area threshold. Polygons below this area are culled as numerical debris (Default: 1e-4) */
    minArea?: number;
}

import { Scene, Circle, Rect, BooleanOps, Color } from "retiam";

const scene = new Scene({ canvas });

// Create two overlapping geometric operands
const circle = new Circle(2.5, {
    position: [-1.0, 0, 0],
    fill: Color.fromHex("#3b82f6")
});

const rect = new Rect(4.0, 4.0, {
    position: [1.0, 0, 0],
    fill: Color.fromHex("#ec4899")
});

// Compute Venn diagram intersection lens
const lens = BooleanOps.intersection(circle, rect, {
    fill: Color.fromHex("#a855f7"),
    stroke: Color.WHITE,
    stroke_width: 0.08,
    reconstructCurves: true
});

scene.add(lens);
